-- Navi AI Career: initial schema (generated from db/schema.ts) for Turso DB `morriztech`
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS "user" (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS "session" (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, token TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS "account" (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS "verification" (id TEXT PRIMARY KEY NOT NULL, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, display_name TEXT, target_role TEXT, current_level TEXT CHECK (current_level IN ('beginner','intermediate','advanced')), weekly_hours INTEGER, target_months INTEGER, learning_preference TEXT, skills TEXT, timezone TEXT NOT NULL DEFAULT 'Asia/Jakarta', reminder_time TEXT, reminders_enabled INTEGER NOT NULL DEFAULT 0, onboarded_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS learning_plans (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, title TEXT NOT NULL, summary TEXT, source TEXT NOT NULL DEFAULT 'template' CHECK (source IN ('template','gemini')), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived','completed')), created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS learning_plans_user_idx ON learning_plans (user_id, status);
CREATE TABLE IF NOT EXISTS plan_milestones (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, plan_id TEXT NOT NULL REFERENCES learning_plans(id) ON DELETE CASCADE, position INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, week_start INTEGER, week_end INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS plan_milestones_plan_idx ON plan_milestones (plan_id);
CREATE TABLE IF NOT EXISTS plan_tasks (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, milestone_id TEXT NOT NULL REFERENCES plan_milestones(id) ON DELETE CASCADE, position INTEGER NOT NULL, title TEXT NOT NULL, resource_url TEXT, estimated_minutes INTEGER, completed_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS plan_tasks_user_idx ON plan_tasks (user_id);
CREATE INDEX IF NOT EXISTS plan_tasks_milestone_idx ON plan_tasks (milestone_id);
CREATE TABLE IF NOT EXISTS memory_facts (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, content TEXT NOT NULL, category TEXT, pinned INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS memory_facts_user_idx ON memory_facts (user_id);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, title TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS conversations_user_idx ON conversations (user_id);
CREATE TABLE IF NOT EXISTS chat_messages (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user','assistant')), content TEXT NOT NULL, source TEXT CHECK (source IN ('gemini','fixture')), created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS chat_messages_conv_idx ON chat_messages (conversation_id, created_at);
CREATE TABLE IF NOT EXISTS job_applications (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, company TEXT NOT NULL, position TEXT NOT NULL, url TEXT, location TEXT, salary_range TEXT, status TEXT NOT NULL DEFAULT 'wishlist' CHECK (status IN ('wishlist','applied','interview','offer','rejected','ghosted')), applied_at INTEGER, notes TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS job_applications_user_idx ON job_applications (user_id, status);
CREATE TABLE IF NOT EXISTS cv_reviews (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, target_role TEXT, cv_text TEXT NOT NULL, score INTEGER, feedback TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS cv_reviews_user_idx ON cv_reviews (user_id);
CREATE TABLE IF NOT EXISTS streaks (user_id TEXT PRIMARY KEY NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, current_streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0, last_active_date TEXT, updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS activity_log (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK (type IN ('task_completed','chat','cv_review','job_update','login')), ref_id TEXT, activity_date TEXT NOT NULL, minutes INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS activity_user_date_idx ON activity_log (user_id, activity_date);
CREATE TABLE IF NOT EXISTS rate_limits ("key" TEXT NOT NULL, window_start INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS rate_limits_key_window ON rate_limits ("key", window_start);
